/* @component: .fade-slider-section */
function initFadeSwiper() {
  if (typeof Swiper !== 'undefined') {
    new Swiper('.fadeSwiper', {
      loop: true,
      effect: 'fade',
      fadeEffect: { crossFade: true },
      speed: 1000,
      autoplay: { delay: 4000, disableOnInteraction: false },
      allowTouchMove: false,
      observer: true,
      observeParents: true,
    });
  } else {
    setTimeout(initFadeSwiper, 150);
  }
}

// Умная загрузка ресурсов (только 1 раз)
if (!document.getElementById('swiper-css')) {
  const link = document.createElement('link');
  link.id = 'swiper-css';
  link.rel = 'stylesheet';
  link.href = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css';
  document.head.appendChild(link);
}

if (!document.getElementById('swiper-js')) {
  const script = document.createElement('script');
  script.id = 'swiper-js';
  script.src = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js';
  script.onload = initFadeSwiper;
  document.head.appendChild(script);
} else {
  initFadeSwiper();
}
